import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        PriorityQueue<Long> heap = new PriorityQueue<>();
        for (int i = 0; i < n; i++) heap.add(next());
        // Huffman merging: always combine the two smallest values.
        long cost = 0;
        while (heap.size() > 1) {
            long value = heap.poll() + heap.poll();
            cost += value;
            heap.add(value);
        }
        System.out.println(cost);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

type minHeap []int64

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	h := make(minHeap, n)
	for i := range h {
		h[i] = next()
	}
	heap.Init(&h)
	// Huffman merging: always combine the two smallest values.
	var cost int64
	for h.Len() > 1 {
		value := heap.Pop(&h).(int64) + heap.Pop(&h).(int64)
		cost += value
		heap.Push(&h, value)
	}
	fmt.Println(cost)
}
